
.variable-update-container {
  margin-bottom: 0.5rem;
}

.variable-update-details {
  background: linear-gradient(135deg, var(--warm-bg-light) 0%, var(--warm-bg-medium) 100%);
  border-radius: 0.5rem;
  box-shadow: 0 2px 8px var(--warm-shadow);
  overflow: hidden;
  transition: all 0.3s ease;

  &[open] {
    box-shadow: 0 4px 12px var(--warm-shadow);
  }
}

.variable-update-summary {
  padding: 0.5rem 0.75rem;
  color: var(--text-title);
  font-family: var(--font-title);
  font-size: 0.85rem;
  cursor: pointer;
  list-style: none;
  transition: all 0.2s ease;
  display: flex;
  justify-content: space-between;
  align-items: center;

  &:hover {
    background-color: var(--warm-hover-bg);
  }

  &::marker {
    display: none;
  }
}

.toggle-hint {
  font-family: var(--font-serif);
  font-size: 0.7rem;
  color: var(--text-secondary);
  transition: transform 0.3s ease;
}

.variable-update-details[open] .toggle-hint::after {
  content: attr(data-open);
}

.variable-update-details:not([open]) .toggle-hint::after {
  content: attr(data-close);
}

.variable-update-content {
  display: block;
  width: 100%;
  min-height: 2rem;
  overflow-y: auto;
  padding: 0.5rem 0.75rem;
  color: var(--text-primary);
  font-size: 0.75rem;
  line-height: 1.6;
  white-space: pre-wrap;
  word-wrap: break-word;
  background-color: var(--bg-panel);
  border: none;
  resize: none;
  font-family: inherit;
  box-sizing: border-box;
  animation: fadeIn 0.3s ease;
  field-sizing: content;

  &::-webkit-scrollbar {
    width: 4px;
  }

  &::-webkit-scrollbar-track {
    background: var(--warm-bg-dark);
  }

  &::-webkit-scrollbar-thumb {
    background: var(--border-color);
    border-radius: 2px;
  }
}

.json-validate-result {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.5rem 0.75rem;
  font-size: 0.7rem;
  color: var(--text-secondary);
  background-color: var(--warm-bg-dark);
  border-top: 1px solid var(--border-color);
}

.validate-text {
  flex: 1;
}

.action-buttons {
  display: flex;
  gap: 0.5rem;
}

.action-btn {
  padding: 0.25rem 0.5rem;
  font-size: 0.65rem;
  color: var(--text-primary);
  background-color: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: 0.25rem;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    background-color: var(--warm-hover-bg);
    border-color: var(--user-color-primary);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
